/** 2022-11-16 Nina Script for component guide*/
INSERT INTO T_CK_COMPONENT_GUIDE(CMGU_ID, CMGU_APPS_CODE, CMGU_SERVICE_TYPE, CMGU_COMPONENT_ID, CMGU_GUIDE, CMGU_GUIDE_OTH, CMGU_STATUS, CMGU_DT_CREATE, CMGU_UID_CREATE, CMGU_DT_LUPD, CMGU_UID_LUPD)  VALUES('1','CK','CLICDO','clicdo.doi.co.jobs.list','When a job is submitted, it is locked and its fields cannot be edited. If there are errors associated with the submitted job, it has to be cancelled before it is picked up for processing by the authorized party (aka Freight Forwarder)',NULL,'A',NOW(),'SYS',NOW(),'SYS');
INSERT INTO T_CK_COMPONENT_GUIDE(CMGU_ID, CMGU_APPS_CODE, CMGU_SERVICE_TYPE, CMGU_COMPONENT_ID, CMGU_GUIDE, CMGU_GUIDE_OTH, CMGU_STATUS, CMGU_DT_CREATE, CMGU_UID_CREATE, CMGU_DT_LUPD, CMGU_UID_LUPD)  VALUES('2','CK','CLICDO','clicdo.doi.co.jobs.list.table','Each job recordi n the list corresponds to job corresponding to a Bill of Lading (BL) document. These jobs when submitted will be picked up by the Authorized Party (aka Freight Forwarders) stated in the job for DO claiming. Click on eye icon to view the BL in PDF and the cancel icon to cancel the job.',NULL,'A',NOW(),'SYS',NOW(),'SYS');
INSERT INTO T_CK_COMPONENT_GUIDE(CMGU_ID, CMGU_APPS_CODE, CMGU_SERVICE_TYPE, CMGU_COMPONENT_ID, CMGU_GUIDE, CMGU_GUIDE_OTH, CMGU_STATUS, CMGU_DT_CREATE, CMGU_UID_CREATE, CMGU_DT_LUPD, CMGU_UID_LUPD)  VALUES('3','CK','CLICDO','clicdo.doi.co.jobs.tabs.details','Update all the information to ensure correct information about the job is captured. Click Save to save the updated job or click Submit to submit the job to the Authorized Party.',NULL,'A',NOW(),'SYS',NOW(),'SYS');
INSERT INTO T_CK_COMPONENT_GUIDE(CMGU_ID, CMGU_APPS_CODE, CMGU_SERVICE_TYPE, CMGU_COMPONENT_ID, CMGU_GUIDE, CMGU_GUIDE_OTH, CMGU_STATUS, CMGU_DT_CREATE, CMGU_UID_CREATE, CMGU_DT_LUPD, CMGU_UID_LUPD)  VALUES('4','CK','CLICDO','clicdo.doi.co.jobs.tabs.authorisation','Document will be reviewed by shipping line. If there are concerns, the owner of the job will be contacted via email for clarifications. Only after the documents and payment are verified will your Authorized Party be able to download the invoice and start the DO claim process.',NULL,'A',NOW(),'SYS',NOW(),'SYS');
