/** 2022-12-06 Bill - added new table for payment */
CREATE TABLE `T_CK_PAYMENT_TXN` (
  `PTX_ID` varchar(35) NOT NULL COMMENT 'PAYMENT TXN ID - UUID',
  `PTX_TYPE` varchar(35) DEFAULT NULL COMMENT 'PAYMENT TYPE - REFERENCE T_CK_MST_PAYMENT_TYPE:PTY_ID',
  `PTX_SVC` varchar(35) DEFAULT NULL COMMENT 'CLICKARGO SERVICES - REFERENCE T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `PTX_SVC_REF` varchar(2048) DEFAULT NULL COMMENT 'JOB OR TASK ID REFERENCE FOR THE PAYMENT',
  `PTX_MERCHANT_BANK` varchar(35) DEFAULT NULL COMMENT 'PAYMENT MERCHANT BANK',
  `PTX_PAYER` varchar(35) DEFAULT NULL COMMENT 'PAYER - REFERENCES T_CORE_ACCN:ACCN_ID',
  `PTX_PAYER_BANK_ACCN` varchar(255) DEFAULT NULL COMMENT 'PAYER BANK ACCOUNT NUMBER',
  `PTX_PAYEE` varchar(35) DEFAULT NULL COMMENT 'PAYEE - REFERENCES T_CORE_ACCN:ACCN_ID',
  `PTX_PAYEE_BANK_ACCN` varchar(255) DEFAULT NULL COMMENT 'PAYER BANK ACCOUNT NUMBER',
  `PTX_AMOUNT` decimal(15,2) DEFAULT '0.00' COMMENT 'PAYMENT AMOUNT - 12,0000',
  `PTX_CCY` varchar(3) DEFAULT NULL COMMENT 'CURRENCY  - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `PTX_BANK_REF` varchar(255) DEFAULT NULL COMMENT 'BANK REFERENCE NUMBER - VA',
  `PTX_PAYMENT_STATE` varchar(35) DEFAULT NULL COMMENT 'PAYMENT STATE - SUCCESS : FAIL : NEW',
  `PTX_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `PTX_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `PTX_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `PTX_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `PTX_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`PTX_ID`),
  KEY `FK_CK_PAYMENT_TXN_CK_MST_PAYMENT_TYPE` (`PTX_TYPE`),
  KEY `FK_CK_PAYMENT_TXN_CK_MST_SERVICE_TYPE` (`PTX_SVC`),
  KEY `FK_CK_PAYMENT_TXN_CORE_ACCN1` (`PTX_PAYER`),
  KEY `FK_CK_PAYMENT_TXN_CORE_ACCN2` (`PTX_PAYEE`),
  KEY `FK_CK_PAYMENT_TXN_MST_CCY` (`PTX_CCY`),
  CONSTRAINT `FK_CK_PAYMENT_TXN_CK_MST_PAYMENT_TYPE` FOREIGN KEY (`PTX_TYPE`) REFERENCES `T_CK_MST_PAYMENT_TYPE` (`PTY_ID`),
  CONSTRAINT `FK_CK_PAYMENT_TXN_CK_MST_SERVICE_TYPE` FOREIGN KEY (`PTX_SVC`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_PAYMENT_TXN_CORE_ACCN1` FOREIGN KEY (`PTX_PAYER`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_PAYMENT_TXN_CORE_ACCN2` FOREIGN KEY (`PTX_PAYEE`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_PAYMENT_TXN_MST_CCY` FOREIGN KEY (`PTX_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='PAYMENT TXN TABLE';


CREATE TABLE `T_CK_PAYMENT_TXN_INVOICE` (
  `PTI_ID` varchar(35) NOT NULL COMMENT 'PAYMENT TRANSACTION INVOCE REF ID - UUID',  
  `PTI_TXN_ID` varchar(35) NOT NULL COMMENT 'PAYMENT TXN - REFERENCE T_CK_PAYMENT_TXN:PTX_ID',
  `PTI_INV_ID` varchar(35) NOT NULL COMMENT 'PAYMENT TXN INVOICE ID',
  `PTI_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `PTI_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `PTI_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `PTI_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `PTI_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`PTI_ID`),
  CONSTRAINT `FK_CK_PAYMENT_TXN_INVOICE_CK_PAYMENT_TXN` FOREIGN KEY (`PTI_TXN_ID`) REFERENCES `T_CK_PAYMENT_TXN` (`PTX_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='PAYMENT TXN INVOICE REFERENCE';


/** 2022-12-06 Bill - added new tables for base DO */
CREATE TABLE `T_CK_DO` (
  `DO_ID` varchar(35) NOT NULL COMMENT 'DO IMPORT ID - UUID',
  `DO_SHIPMENT_TYPE` varchar(35) NOT NULL COMMENT 'DO SHIPMENT TYPE - REFERENCES T_CK_MST_SHIPMENT_TYPE:SHT_ID',
  `DO_NO` varchar(255) DEFAULT NULL COMMENT 'DO NUMBER',
  `DO_VESSEL_NO` varchar(255) DEFAULT NULL COMMENT 'DO VESSEL OFFICAL NO (VON) - CG002972',
  `DO_VESSEL_NAME` varchar(255) DEFAULT NULL COMMENT 'DO VESSEL NAME - EVERGREEN TERESA',
  `DO_VESSEL_ETA` datetime DEFAULT NULL COMMENT 'DO VESSEL ESTIMATED ARRIVAL TIME - 20201001',
  `DO_VESSEL_ATA` datetime DEFAULT NULL COMMENT 'DO VESSEL ACTUAL ARRIVAL TIME - 20201001 00:00:00',
  `DO_VESSEL_ETD` datetime DEFAULT NULL COMMENT 'DO VESSEL ESTIMATED DEPARTURE TIME - 20201001',
  `DO_VESSEL_ATD` datetime DEFAULT NULL COMMENT 'DO VESSEL ACTUAL DEPARTURE TIME - 20201001 00:00:00',
  `DO_VOYAGE_NO` varchar(255) DEFAULT NULL COMMENT 'DO VOYAGE NO - V.284',
  `DO_TERMINAL` varchar(255) DEFAULT NULL COMMENT 'DO TERMINAL OF DISCHARGE',
  `DO_POL` varchar(5) DEFAULT NULL COMMENT 'DO PORT OF LOADING - REFERENCE T_MST_PORT:PORT_CODE',
  `DO_POD` varchar(5) DEFAULT NULL COMMENT 'DO PORT OF DISCHARGE - REFERENCE T_MST_PORT:PORT_CODE',
  `DO_NO_CNT` smallint DEFAULT '0' COMMENT 'DO NUMBER OF CONTAINERS',
  `DO_STATE` varchar(35) DEFAULT NULL COMMENT 'DO STATE - REFERENCE T_CK_MST_DO_STATE:DOST_ID',
  `DO_DT_DO_SUBMIT` datetime DEFAULT NULL COMMENT 'DO SUBMITTED DATE',
  `DO_DT_DO_CLAIM` datetime DEFAULT NULL COMMENT 'DO CLAIM DATE',
  `DO_DO` varchar(1024) DEFAULT NULL COMMENT 'DO ATTACHMENT PATH REFERENCE FROM SYS_PARAM SETUP',
  `DO_STATUS` char(1) DEFAULT NULL COMMENT 'DO STATUS - A : I ',
  `DO_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DO_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DO_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DO_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DO_ID`),
  KEY `FK_CK_DO_CK_MST_DO_STATE` (`DO_STATE`),
  KEY `FK_CK_DO_CK_MST_SHIPMENT_TYPE` (`DO_SHIPMENT_TYPE`),
  CONSTRAINT `FK_CK_DO_CK_MST_DOI_STATE` FOREIGN KEY (`DO_STATE`) REFERENCES `T_CK_MST_DO_STATE` (`DOST_ID`),  
  CONSTRAINT `FK_CK_DO_CK_MST_SHIPMENT_TYPE` FOREIGN KEY (`DO_SHIPMENT_TYPE`) REFERENCES `T_CK_MST_SHIPMENT_TYPE` (`SHT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DELIVERY ORDER TABLE';

-- DELIVERY ORDER PARTY -------------------------------------------------------------------------------
CREATE TABLE `T_CK_MST_DO_PARTY_TYPE` (
  `DOPT_ID` varchar(35) NOT NULL COMMENT 'DO PARTY TYPE ID - CONSINGEE : NOTIFY',
  `DOPT_NAME` varchar(100) NOT NULL COMMENT 'DO PARTY TYPE NAME',
  `DOPT_DESC` varchar(255) DEFAULT NULL COMMENT 'DO PARTY TYPE DESCRIPTION',
  `DOPT_DESC_OTH` varchar(512) DEFAULT NULL COMMENT 'DO PARTY TYPE  DESCRIPTION OTHER LANGUAGE',
  `DOPT_STATUS` char(1) DEFAULT NULL COMMENT 'DO PARTY TYPE STATUS',
  `DOPT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DOPT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DOPT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DOPT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DOPT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DO PARTY TYPE TABLE';

