CREATE TABLE `T_CK_DO_PARTY` (
  `DOP_DO_ID` varchar(35) NOT NULL COMMENT 'DO PARTY DO ID - REFERENCES T_CK_DO:DO_ID',
  `DOP_TYPE` varchar(35) NOT NULL COMMENT 'DO PARTY TYPE - REFERENCES T_CK_MST_DO_PARTY_TYPE:DOPT_ID',
  `DOP_USR` varchar(35) DEFAULT NULL COMMENT 'DO CONSIGNEE USER DETALS - REFERENCE T_CORE_USR:USR_UID',
  `DO_ACCN` varchar(35) DEFAULT NULL COMMENT 'DO CONSIGNEE ACCN DETALS - REFERENCE T_CORE_ACCN:ACCN_ID',
  `DOP_STATUS` char(1) DEFAULT NULL COMMENT 'DO PARTY TYPE STATUS',
  `DOP_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DOP_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DOP_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DOP_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DOP_DO_ID`, `DOP_TYPE`),
  CONSTRAINT `FK_CK_DO_PARTY_CK_DO` FOREIGN KEY (`DOP_DO_ID`) REFERENCES `T_CK_DO` (`DO_ID`),
  CONSTRAINT `FK_CK_DO_PARTY_CK_MST_DO_PARTY_TYPE` FOREIGN KEY (`DOP_TYPE`) REFERENCES `T_CK_MST_DO_PARTY_TYPE` (`DOPT_ID`),
  CONSTRAINT `FK_CK_DO_PARTY_CORE_USR` FOREIGN KEY (`DOP_USR`) REFERENCES `T_CORE_USR` (`USR_UID`),
  CONSTRAINT `FK_CK_DO_PARTY_CORE_ACCN` FOREIGN KEY (`DO_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DELIVERY ORDER PARTY TABLE';

