  `INV_ID` varchar(35) NOT NULL COMMENT 'INVOICE ID - UUID',
  `INV_DO_ID` varchar(35) NOT NULL COMMENT 'DO RELATED TO THE INVOICE - REFERECNES T_CK_DO:DO_ID',
  `INV_NO` varchar(255) NOT NULL COMMENT 'INVOICE NUMBER - IMF2001535',
