  `INV_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `INV_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `INV_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',    
  PRIMARY KEY (`INV_ID`),
  CONSTRAINT `FK_CK_DOI_INVOICE_CK_DO` FOREIGN KEY (`INV_DO_ID`) REFERENCES `T_CK_DO` (`DO_ID`),
  CONSTRAINT `FK_CK_DOI_INVOICE_CK_MST_INVOICE_TYPE` FOREIGN KEY (`INV_TYPE`) REFERENCES `T_CK_MST_INVOICE_TYPE` (`INVT_ID`),
  CONSTRAINT `FK_CK_DOI_INVOICE_MST_CCY` FOREIGN KEY (`INV_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DO INVOICE TYPE TABLE'; 


ALTER TABLE `clickargo`.`T_CK_DO_INVOICE` 
ADD COLUMN `INV_DO_REGION` VARCHAR(255) NULL DEFAULT NULL AFTER `INV_DO_ID`;



